// Package agentusageview is the `:agent-usage` screen.
//
// RED-PHASE STUB: signatures only, no behavior. Step 2 of DEVDESK-41 replaces
// this file with the real model.
package agentusageview

import (
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

type sessionRow struct {
	agentusage.Session
	project string
}

type sessionListLoadedMsg struct {
	gen     int
	root    string
	listing agentusage.Listing
	err     error
}

// Model is the stub.
type Model struct {
	gen     int
	loading bool
	table   datatable.Model[sessionRow]
}

func New(_ *config.Config) Model { return Model{} }

func sessionColumns() []datatable.Column[sessionRow] { return nil }

func listSessionsCmd(_ int) tea.Cmd { return func() tea.Msg { return nil } }

func (m Model) Init() tea.Cmd                              { return nil }
func (m Model) Update(tea.Msg) (tea.Model, tea.Cmd)        { return m, nil }
func (m Model) View() string                               { return "" }
func (m Model) GetTitle() string                           { return "" }
func (m Model) GetIcon() string                            { return "" }
func (m Model) GetHeaderInfo(string) []shortcut.HeaderInfo { return nil }
func (m Model) GetShortcuts() shortcut.Shortcuts           { return nil }
func (m Model) GetFooterHeight() int                       { return 0 }
func (m Model) RenderFooter(int) string                    { return "" }
func (m Model) InEditMode() bool                           { return false }
func (m Model) FilterBarVisible() bool                     { return false }
func (m Model) GetHelpContent() help.Content               { return help.Content{} }

