1	package agentusageview
2	
3	import (
4		"errors"
5		"io"
6		"log"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11		"time"
12	
13		"github.com/charmbracelet/bubbles/spinner"
14		tea "github.com/charmbracelet/bubbletea"
15	
16		"github.com/anthnel/devdesk/internal/agentusage"
17		"github.com/anthnel/devdesk/internal/config"
18		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
19		"github.com/anthnel/devdesk/internal/ui/datatable"
20		"github.com/anthnel/devdesk/internal/ui/help"
21		"github.com/anthnel/devdesk/internal/ui/testutil"
22	)
23	
24	// TestMain points HOME and CLAUDE_CONFIG_DIR at a temp dir for the whole
25	// process, so no test can read the developer's real transcripts.
26	func TestMain(m *testing.M) {
27		log.SetOutput(io.Discard)
28		sharedcomponents.FooterMsgDuration = time.Millisecond
29	
30		home, err := os.MkdirTemp("", "agentusageview-home-")
31		if err != nil {
32			panic(err)
33		}
34		os.Setenv("HOME", home)
35		os.Setenv("USERPROFILE", home)
36		os.Setenv("CLAUDE_CONFIG_DIR", filepath.Join(home, ".claude"))
37	
38		code := m.Run()
39		os.RemoveAll(home)
40		os.Exit(code)
41	}
42	
43	// ── Fixtures ─────────────────────────────────────────────────────────────────
44	
45	// isolate gives one test its own HOME and config dir.
46	func isolate(t *testing.T) string {
47		t.Helper()
48		home := t.TempDir()
49		t.Setenv("HOME", home)
50		t.Setenv("USERPROFILE", home)
51		t.Setenv("CLAUDE_CONFIG_DIR", filepath.Join(home, ".claude"))
52		return home
53	}
54	
55	var base = time.Date(2026, 9, 1, 10, 30, 0, 0, time.Local)
56	
57	func session(id, project string, age time.Duration) agentusage.Session {
58		return agentusage.Session{ID: id, Project: project, ModTime: base.Add(-age)}
59	}
60	
61	// newModel builds a sized model with the first read still in flight.
62	func newModel(t *testing.T) Model {
63		t.Helper()
64		isolate(t)
65		return feed(t, New(config.Default()), testutil.Resize(120, 20))
66	}
67	
68	func feed(t *testing.T, m Model, msg tea.Msg) Model {
69		t.Helper()
70		updated, _ := m.Update(msg)
71		next, ok := updated.(Model)
72		if !ok {
73			t.Fatalf("Update returned %T, want agentusageview.Model", updated)
74		}
75		return next
76	}
77	
78	// loaded delivers a listing carrying the model's current generation.
79	func loaded(t *testing.T, m Model, sessions ...agentusage.Session) Model {
80		t.Helper()
81		return feed(t, m, sessionListLoadedMsg{
82			gen:     m.gen,
83			root:    filepath.Join(os.Getenv("HOME"), ".claude", "projects"),
84			listing: agentusage.Listing{Sessions: sessions},
85		})
86	}
87	
88	func sessionsValue(t *testing.T, m Model) string {
89		t.Helper()
90		for _, h := range m.GetHeaderInfo("") {
91			if h.Key == "Sessions" {
92				return h.Value
93			}
94		}
95		t.Fatalf("no Sessions header field in %+v", m.GetHeaderInfo(""))
96		return ""
97	}
98	
99	func footer(m Model) string { return m.RenderFooter(120) }
100	
101	// ── Loading ──────────────────────────────────────────────────────────────────
102	
103	func TestInitReadsTheListingAndStartsTheSpinner(t *testing.T) {
104		m := New(config.Default())
105		if !m.loading {
106			t.Fatal("a new model is loading")
107		}
108		if m.Init() == nil {
109			t.Fatal("Init returns the read and the spinner tick")
110		}
111	}
112	
113	func TestWhileLoadingTheTableKeepsItsHeadersAndHasNoRows(t *testing.T) {
114		m := newModel(t)
115		view := m.View()
116		for _, title := range []string{"Project", "Last active"} {
117			if !strings.Contains(view, title) {
118				t.Errorf("loading view lacks column %q:\n%s", title, view)
119			}
120		}
121		if got := sessionsValue(t, m); got != "0" {
122			t.Errorf("Sessions = %q while loading, want 0", got)
123		}
124		f := footer(m)
125		if !strings.Contains(f, "Reading Claude Code sessions...") {
126			t.Errorf("footer should show the loading status:\n%s", f)
127		}
128		if strings.Contains(f, "No Claude Code sessions") {
129			t.Error("the empty message must wait for the load to finish")
130		}
131	}
132	
133	func TestASpinnerTickWhileNotLoadingIsDropped(t *testing.T) {
134		m := loaded(t, newModel(t), session("a", "/x", 0))
135		_, cmd := m.Update(spinnerTick())
136		if cmd != nil {
137			t.Error("a tick after the load must not reschedule itself")
138		}
139	}
140	
141	// ── Rows ─────────────────────────────────────────────────────────────────────
142	
143	func TestRowsKeepTheOrderGivenNewestFirst(t *testing.T) {
144		m := newModel(t)
145		home := os.Getenv("HOME")
146		m = loaded(t, m,
147			session("11111111-aaaa", filepath.Join(home, "work", "newest"), 1*time.Hour),
148			session("22222222-bbbb", filepath.Join(home, "work", "middle"), 5*time.Hour),
149			session("33333333-cccc", "/srv/oldest", 48*time.Hour),
150		)
151		view := m.View()
152		order := []string{"newest", "middle", "oldest"}
153		last := -1
154		for _, name := range order {
155			i := strings.Index(view, name)
156			if i < 0 {
157				t.Fatalf("project %q missing from view:\n%s", name, view)
158			}
159			if i < last {
160				t.Errorf("%q is out of order (recent-to-old expected):\n%s", name, view)
161			}
162			last = i
163		}
164		if got := sessionsValue(t, m); got != "3" {
165			t.Errorf("Sessions = %q, want 3", got)
166		}
167	}
168	
169	func TestProjectIsTheFullPathWithHomeFoldedToATilde(t *testing.T) {
170		m := newModel(t)
171		home := os.Getenv("HOME")
172		m = loaded(t, m, session("11111111-aaaa", filepath.Join(home, "projects", "devdesk"), time.Hour))
173		view := m.View()
174		if !strings.Contains(view, "~/projects/devdesk") {
175			t.Errorf("project should read ~/projects/devdesk:\n%s", view)
176		}
177		if strings.Contains(view, home) {
178			t.Errorf("the home directory must be folded, found %q", home)
179		}
180	}
181	
182	func TestAMissingProjectIsADash(t *testing.T) {
183		m := loaded(t, newModel(t), session("11111111-aaaa", "", time.Hour))
184		if !strings.Contains(m.View(), "-") {
185			t.Errorf("an unknown project renders a dash:\n%s", m.View())
186		}
187	}
188	
189	func TestLastActiveReadsAsLocalDateAndTime(t *testing.T) {
190		m := loaded(t, newModel(t), session("11111111-aaaa", "/srv/p", 0))
191		want := base.Format("2006-01-02 15:04")
192		if !strings.Contains(m.View(), want) {
193			t.Errorf("view should contain %q:\n%s", want, m.View())
194		}
195	}
196	
197	func TestSessionColumnShowsTheLeadingIDAndSearchUsesTheFullOne(t *testing.T) {
198		cols := sessionColumns()
199		if len(cols) != 3 {
200			t.Fatalf("want 3 columns (Project, Last active, Session), got %d", len(cols))
201		}
202		for i, title := range []string{"Project", "Last active", "Session"} {
203			if cols[i].Title != title {
204				t.Errorf("column %d = %q, want %q", i, cols[i].Title, title)
205			}
206		}
207		full := "abcdef12-3456-7890-abcd-ef1234567890"
208		row := sessionRow{Session: session(full, "/srv/p", 0), project: "/srv/p"}
209		if cell := cols[2].Cell(row); cell == "" || !strings.HasPrefix(full, cell) {
210			t.Errorf("Session cell %q should be a prefix of the ID", cell)
211		}
212		if cols[2].Search == nil || cols[2].Search(row) != full {
213			t.Error("Session column must search on the full ID")
214		}
215		if cols[0].Search == nil || cols[0].Search(row) != "/srv/p" {
216			t.Error("Project column must search on the project")
217		}
218	}
219	
220	func TestTheProjectColumnTruncatesFromTheLeft(t *testing.T) {
221		cols := sessionColumns()
222		if len(cols) == 0 || !cols[0].TruncateHead {
223			t.Error("Project must truncate from the left so the leaf stays visible")
224		}
225		if len(cols) > 0 && cols[0].Flex == 0 {
226			t.Error("Project should flex to take the spare width")
227		}
228	}
229	
230	// ── Empty, error, stale ──────────────────────────────────────────────────────
231	
232	// Rule 139: zero sessions is a table with headers and no rows; the message
233	// belongs to the footer.
234	func TestZeroSessionsKeepsTheTableAndSaysSoInTheFooter(t *testing.T) {
235		m := loaded(t, newModel(t))
236		view := m.View()
237		for _, title := range []string{"Project", "Last active"} {
238			if !strings.Contains(view, title) {
239				t.Errorf("empty view lacks column %q:\n%s", title, view)
240			}
241		}
242		if strings.Contains(view, "No Claude Code sessions") {
243			t.Error("the body must stay a table; the message is the footer's")
244		}
245		if got := sessionsValue(t, m); got != "0" {
246			t.Errorf("Sessions = %q, want 0", got)
247		}
248		if f := footer(m); !strings.Contains(f, "No Claude Code sessions found") {
249			t.Errorf("footer should say no sessions were found:\n%s", f)
250		}
251		if f := footer(m); strings.Contains(f, "Reading Claude Code sessions") {
252			t.Error("loading status must be gone once the read finished")
253		}
254	}
255	
256	func TestTheEmptyMessageNamesTheRootWithHomeFolded(t *testing.T) {
257		m := loaded(t, newModel(t))
258		if f := footer(m); !strings.Contains(f, "~/.claude/projects") {
259			t.Errorf("footer should name the folded root:\n%s", f)
260		}
261	}
262	
263	func TestAFilterWithNoMatchIsNotAnEmptyListing(t *testing.T) {
264		m := loaded(t, newModel(t), session("11111111-aaaa", "/srv/alpha", time.Hour))
265		m = send(t, m, testutil.Key("/"))
266		for _, k := range testutil.Type("zzz") {
267			m = feed(t, m, k)
268		}
269		if got := sessionsValue(t, m); got != "0" {
270			t.Errorf("Sessions = %q under a filter with no match, want 0", got)
271		}
272		if f := footer(m); strings.Contains(f, "No Claude Code sessions") {
273			t.Errorf("a filter with no match must not claim there are no sessions:\n%s", f)
274		}
275	}
276	
277	func TestAnErrorIsReportedInTheFooterAndKeepsTheRows(t *testing.T) {
278		m := loaded(t, newModel(t), session("11111111-aaaa", "/srv/alpha", time.Hour))
279		m = feed(t, m, sessionListLoadedMsg{gen: m.gen, err: errors.New("agentusage: projects is not a directory")})
280		f := footer(m)
281		if !strings.Contains(f, "Failed to list Claude Code sessions") {
282			t.Errorf("footer should report the failure:\n%s", f)
283		}
284		if strings.Contains(f, "is not a directory") {
285			t.Error("the raw error is logged, not shown (Rule 128)")
286		}
287		if !strings.Contains(m.View(), "/srv/alpha") {
288			t.Error("rows already shown must be kept after a failed refresh")
289		}
290		if got := sessionsValue(t, m); got != "1" {
291			t.Errorf("Sessions = %q, want 1", got)
292		}
293	}
294	
295	func TestAnErrorOnTheFirstReadShowsNoEmptyMessage(t *testing.T) {
296		m := feed(t, newModel(t), sessionListLoadedMsg{gen: 0, err: errors.New("boom")})
297		f := footer(m)
298		if !strings.Contains(f, "Failed to list Claude Code sessions") {
299			t.Errorf("footer should report the failure:\n%s", f)
300		}
301		if strings.Contains(f, "No Claude Code sessions") {
302			t.Error("a failure is not an empty listing")
303		}
304	}
305	
306	func TestOmittedSessionsAppearInTheHeaderOnlyWhenThereAreSome(t *testing.T) {
307		m := newModel(t)
308		m = loaded(t, m, session("a", "/x", 0))
309		for _, h := range m.GetHeaderInfo("") {
310			if h.Key == "Skipped" {
311				t.Error("Skipped must be absent when nothing was omitted")
312			}
313		}
314		m = feed(t, m, sessionListLoadedMsg{
315			gen:     m.gen,
316			listing: agentusage.Listing{Sessions: []agentusage.Session{session("a", "/x", 0)}, Omitted: 4},
317		})
318		for _, h := range m.GetHeaderInfo("") {
319			if h.Key == "Skipped" {
320				if h.Value != "4" {
321					t.Errorf("Skipped = %q, want 4", h.Value)
322				}
323				return
324			}
325		}
326		t.Error("Skipped header field missing when sessions were omitted")
327	}
328	
329	// ── Generations and refresh ──────────────────────────────────────────────────
330	
331	func TestAStaleListingIsIgnored(t *testing.T) {
332		m := newModel(t)
333		m = feed(t, m, testutil.Key("ctrl+r")) // gen advances
334		stale := sessionListLoadedMsg{
335			gen:     m.gen - 1,
336			listing: agentusage.Listing{Sessions: []agentusage.Session{session("old", "/stale/project", 0)}},
337		}
338		m = feed(t, m, stale)
339		if strings.Contains(m.View(), "stale") {
340			t.Error("a response from an older generation must not reach the table")
341		}
342		if !m.loading {
343			t.Error("the current read is still in flight; a stale answer must not end the load")
344		}
345	}
346	
347	func TestCtrlRStartsANewReadWithANewGeneration(t *testing.T) {
348		m := loaded(t, newModel(t), session("a", "/x", 0))
349		if m.loading {
350			t.Fatal("precondition: load finished")
351		}
352		before := m.gen
353		updated, cmd := m.Update(testutil.Key("ctrl+r"))
354		m = updated.(Model)
355		if m.gen == before {
356			t.Error("ctrl+r must advance the generation")
357		}
358		if !m.loading {
359			t.Error("ctrl+r must set loading")
360		}
361		if cmd == nil {
362			t.Fatal("ctrl+r must return the read command")
363		}
364		if !strings.Contains(m.View(), "/x") {
365			t.Error("rows stay on screen during a refresh (Rule 139)")
366		}
367		if f := footer(m); !strings.Contains(f, "Reading Claude Code sessions...") {
368			t.Errorf("footer should show the refresh:\n%s", f)
369		}
370		// The command built for this generation answers with the same one.
371		msg, ok := testutil.MsgOf[sessionListLoadedMsg](listSessionsCmd(m.gen))
372		if !ok || msg.gen != m.gen {
373			t.Errorf("listSessionsCmd(%d) returned %+v (ok=%v)", m.gen, msg, ok)
374		}
375	}
376	
377	func TestCtrlRWhileTypingInTheFilterIsNotLost(t *testing.T) {
378		// The filter bar owns the keyboard: ctrl+r must not start a read there.
379		m := loaded(t, newModel(t), session("a", "/x", 0))
380		m = send(t, m, testutil.Key("/"))
381		before := m.gen
382		m = send(t, m, testutil.Key("ctrl+r"))
383		if m.gen != before {
384			t.Error("ctrl+r inside the filter must not refresh")
385		}
386	}
387	
388	// End to end: the Cmd resolves the root and reads the disk itself.
389	func TestListSessionsCmdReadsTheConfiguredRoot(t *testing.T) {
390		home := isolate(t)
391		cfg := t.TempDir()
392		t.Setenv("CLAUDE_CONFIG_DIR", cfg)
393		dir := filepath.Join(cfg, "projects", "-srv-alpha")
394		if err := os.MkdirAll(dir, 0o755); err != nil {
395			t.Fatal(err)
396		}
397		id := "0a1b2c3d-0000-4000-8000-000000000001"
398		line := `{"type":"user","cwd":"` + filepath.Join(home, "alpha") + `"}` + "\n"
399		if err := os.WriteFile(filepath.Join(dir, id+".jsonl"), []byte(line), 0o600); err != nil {
400			t.Fatal(err)
401		}
402	
403		// Called directly: testutil.Msgs on the batch would wait for the tick.
404		msg, ok := listSessionsCmd(0)().(sessionListLoadedMsg)
405		if !ok {
406			t.Fatal("listSessionsCmd must return a sessionListLoadedMsg")
407		}
408		if msg.err != nil || len(msg.listing.Sessions) != 1 {
409			t.Fatalf("msg = %+v", msg)
410		}
411		if msg.root != filepath.Join(cfg, "projects") {
412			t.Errorf("root = %q", msg.root)
413		}
414	
415		m := feed(t, New(config.Default()), testutil.Resize(120, 20))
416		m = feed(t, m, msg)
417		if !strings.Contains(m.View(), "~/alpha") {
418			t.Errorf("row missing after the real read:\n%s", m.View())
419		}
420	}
421	
422	func TestAMissingRootIsAnEmptyListingNotAnError(t *testing.T) {
423		isolate(t)
424		msg, ok := listSessionsCmd(0)().(sessionListLoadedMsg)
425		if !ok || msg.err != nil || len(msg.listing.Sessions) != 0 {
426			t.Fatalf("msg = %+v", msg)
427		}
428	}
429	
430	// ── Filter ───────────────────────────────────────────────────────────────────
431	
432	func TestTheFilterNarrowsRowsAndHoldsTheKeyboard(t *testing.T) {
433		m := loaded(t, newModel(t),
434			session("11111111-aaaa", "/srv/alpha", time.Hour),
435			session("22222222-bbbb", "/srv/beta", 2*time.Hour),
436		)
437		m = send(t, m, testutil.Key("/"))
438		if !m.InEditMode() {
439			t.Fatal("/ opens the filter and InEditMode must say so")
440		}
441		for _, k := range testutil.Type("alpha") {
442			m = feed(t, m, k)
443		}
444		if got := sessionsValue(t, m); got != "1" {
445			t.Errorf("Sessions = %q, want 1", got)
446		}
447		view := m.View()
448		if !strings.Contains(view, "alpha") || strings.Contains(view, "beta") {
449			t.Errorf("only the alpha row should remain:\n%s", view)
450		}
451		if !m.FilterBarVisible() {
452			t.Error("the filter bar is visible while filtering")
453		}
454	}
455	
456	func TestFooterHeightFollowsTheFilterBar(t *testing.T) {
457		m := loaded(t, newModel(t), session("a", "/x", 0))
458		if m.GetFooterHeight() != 2 {
459			t.Errorf("footer height = %d, want 2 (Rule 124)", m.GetFooterHeight())
460		}
461		m = send(t, m, testutil.Key("/"))
462		if m.GetFooterHeight() <= 2 {
463			t.Error("the filter bar adds to the footer height (Rule 136)")
464		}
465	}
466	
467	// ── Layout (Rules 108, 116) ──────────────────────────────────────────────────
468	
469	func TestResizeFillsTheViewportExactly(t *testing.T) {
470		m := loaded(t, newModel(t), session("11111111-aaaa", "/srv/alpha", time.Hour))
471		m = feed(t, m, testutil.Resize(80, 20))
472		// RenderedWidth is read through the table the model owns.
473		if got := renderedWidth(m); got != 78 {
474			t.Errorf("rendered width = %d at 80 columns, want 78", got)
475		}
476	}
477	
478	func TestANarrowTerminalDropsSessionFirstAndKeepsProject(t *testing.T) {
479		m := loaded(t, newModel(t), session("11111111-aaaa", "/srv/alpha", time.Hour))
480		m = feed(t, m, testutil.Resize(40, 20))
481		view := m.View()
482		if strings.Contains(view, "Session") {
483			t.Errorf("Session is Optional and goes first at 40 columns:\n%s", view)
484		}
485		if !strings.Contains(view, "Project") {
486			t.Errorf("Project must stay:\n%s", view)
487		}
488	}
489	
490	// ── Shortcuts (Rules 130, 137, 138) ──────────────────────────────────────────
491	
492	func TestShortcutKeysAreTheSameInEveryState(t *testing.T) {
493		loading := newModel(t)
494		empty := loaded(t, newModel(t))
495		rows := loaded(t, newModel(t), session("a", "/x", 0))
496		failed := feed(t, rows, sessionListLoadedMsg{gen: rows.gen, err: errors.New("boom")})
497		filtering := send(t, rows, testutil.Key("/"))
498	
499		want := testutil.ShortcutKeys(loading.GetShortcuts())
500		if len(want) == 0 {
501			t.Fatal("the view advertises no shortcuts")
502		}
503		for _, k := range []string{"ctrl+r", "/", "?"} {
504			if !testutil.HasShortcut(loading.GetShortcuts(), k) {
505				t.Errorf("missing shortcut %q", k)
506			}
507		}
508		states := map[string]Model{"empty": empty, "loaded": rows, "error": failed, "filtering": filtering}
509		for name, m := range states {
510			got := testutil.ShortcutKeys(m.GetShortcuts())
511			if strings.Join(got, ",") != strings.Join(want, ",") {
512				t.Errorf("%s: keys %v differ from loading's %v", name, got, want)
513			}
514		}
515		for name, m := range map[string]Model{"loading": loading, "empty": empty, "loaded": rows, "error": failed, "filtering": filtering} {
516			for _, s := range m.GetShortcuts() {
517				if s.Disabled {
518					t.Errorf("%s: %q is greyed, but every key always acts here", name, s.Key)
519				}
520			}
521		}
522	}
523	
524	func TestShortcutDescriptionsStartWithACapital(t *testing.T) {
525		for _, s := range newModel(t).GetShortcuts() {
526			if s.Description == "" || s.Description[0] < 'A' || s.Description[0] > 'Z' {
527				t.Errorf("%q: description %q must start with a capital (Rule 137)", s.Key, s.Description)
528			}
529		}
530	}
531	
532	// ── Header and help ──────────────────────────────────────────────────────────
533	
534	func TestTheTitleNamesTheView(t *testing.T) {
535		if title := New(config.Default()).GetTitle(); !strings.Contains(title, "Agent usage") {
536			t.Errorf("title = %q", title)
537		}
538		if icon := New(config.Default()).GetIcon(); icon != "" {
539			t.Errorf("the icon lives in the title, got %q", icon)
540		}
541	}
542	
543	func TestHelpDocumentsTheViewAndItsPrivacy(t *testing.T) {
544		var p help.Provider = New(config.Default())
545		c := p.GetHelpContent()
546		if c.Title == "" || c.Description == "" {
547			t.Errorf("help needs a title and a description: %+v", c)
548		}
549		keys := map[string]bool{}
550		for _, b := range c.KeyBindings {
551			keys[b.Key] = true
552		}
553		for _, k := range []string{"ctrl+r", "/", "?"} {
554			if !keys[k] {
555				t.Errorf("help lacks key %q", k)
556			}
557		}
558		if len(c.Sections) < 3 {
559			t.Fatalf("help needs at least 3 sections (columns, sources, privacy), got %d", len(c.Sections))
560		}
561		var all strings.Builder
562		for _, s := range c.Sections {
563			if s.Title == "" || s.Body == "" {
564				t.Errorf("empty help section: %+v", s)
565			}
566			all.WriteString(s.Title + " " + s.Body + " ")
567		}
568		text := strings.ToLower(all.String())
569		for _, want := range []string{"claude_config_dir", "project", "last active", "prompt"} {
570			if !strings.Contains(text, want) {
571				t.Errorf("help should mention %q", want)
572			}
573		}
574	}
575	
576	// ── Conventions copied from jobsview ─────────────────────────────────────────
577	
578	func TestEveryColumnDeclaresItsSizing(t *testing.T) {
579		cols := sessionColumns()
580		if len(cols) == 0 {
581			t.Fatal("the table has no columns")
582		}
583		for _, col := range cols {
584			if col.Sizing == datatable.SizingUnset {
585				t.Errorf("column %q has no Sizing", col.Title)
586			}
587		}
588	}
589	
590	// Rule 122: a cell is measured before it is styled.
591	func TestNoCellCarriesAnEscapeSequence(t *testing.T) {
592		testutil.TrueColor(t)
593		cols := sessionColumns()
594		if len(cols) == 0 {
595			t.Fatal("the table has no columns")
596		}
597		for _, project := range []string{"/srv/alpha", "-", ""} {
598			row := sessionRow{Session: session("0a1b2c3d-0000", project, 0), project: project}
599			for _, col := range cols {
600				if strings.Contains(col.Cell(row), "\x1b") {
601					t.Errorf("column %q returns a styled cell for project %q", col.Title, project)
602				}
603			}
604		}
605	}
606	
607	// ── Helpers ──────────────────────────────────────────────────────────────────
608	
609	func send(t *testing.T, m Model, msg tea.Msg) Model { return feed(t, m, msg) }
610	
611	func spinnerTick() tea.Msg { return spinner.TickMsg{Time: time.Now()} }
612	
613	// renderedWidth is what the table's lines span (Rule 116).
614	func renderedWidth(m Model) int { return m.table.RenderedWidth() }
615

